import csv
rows=list(csv.DictReader(open('indicator_descriptions.csv')))
vals=list(csv.DictReader(open('eurostat_city_values_sample.csv')))
from collections import Counter
cov=Counter(r['indicator_id'] for r in vals)
for th in ['mobility','population_density','environment','living_conditions']:
    print('==',th)
    for r in rows:
        if r['theme']==th:
            print(r['indicator_id'],'|',r['indicator_name'],'|',r['unit'],'|',r['expected_direction'],'| n=',cov.get(r['indicator_id'],0))
""}
